def choose_move(observation):
    wx = observation.get('grid_width', 0)
    wy = observation.get('grid_height', 0)
    pos = observation.get('self_position', [0, 0])
    x, y = pos[0], pos[1]
    resources = observation.get('resources', [])
    opponent_pos = observation.get('opponent_position', None)
    territory_info = observation.get('territory', None)
    settlers = observation.get('settlers', [])
    enemy_resources = observation.get('enemy_resources', [])

    # Defensive extraction with get
    if territory_info is None:
        territory_info = {}
    territory_map = territory_info.get('map', {})

    # Initialize movement targets
    targets = []

    # Prioritize resource collection
    if resources:
        targets.extend(resources)
    # Pursue opponent if nearby (simulate pursuit evasion)
    if opponent_pos:
        targets.append(opponent_pos)
    # Territory control points
    if territory_map:
        # Find unclaimed or least controlled territory
        unclaimed = [pos for pos, owner in territory_map.items() if owner != 'self']
        if unclaimed:
            targets.extend(unclaimed)
    # Settler positions - prevent clustering
    for settler in settlers:
        if abs(settler[0] - x) + abs(settler[1] - y) < 3:
            targets.append(settler)

    if targets:
        # Find the closest target
        def dist(p):
            return abs(p[0] - x) + abs(p[1] - y)
        target = min(targets, key=dist)
        tx, ty = target
        dx = 0
        dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        dx = max(-1, min(1, dx))
        dy = max(-1, min(1, dy))
        # Avoid moving into own territory if possible
        return [dx, dy]
    # No targets, stay put or move randomly
    return [0, 0]
